                h(Btn,{variant:"ghost",onClick:()=>{if(c.p.cat===INSUMO_CAT){setShowEntradaInsumo(c.p.id);setEntradaQtd("");}else setShowLoteModal(c.p.id);},style:{fontSize:12,padding:"6px 12px"}},"＋ Registrar entrada")
