// ─── INTERCORRÊNCIAS — PAINEL GLOBAL ───────────────────────────────────────────
function IntercorrenciasGlobal({patients,setPatients,onSelectPatient,onNav,procedures=[],products=[]}){
  const h=createElement;
  const[fPaciente,setFPaciente]=useState("");
  const[fProc,setFProc]=useState("Todos");
  const[fProd,setFProd]=useState("Todos");
  const[fSev,setFSev]=useState("Todas");
  const[fStatus,setFStatus]=useState("Todos");
  const all=patients.flatMap(p=>(p.intercorrencias||[]).map(ic=>({...ic,patient:p})));
  // ── Alerta de reincidência: 3+ intercorrências graves/emergenciais com o mesmo produto ou região nos últimos 6 meses ──
  const recentCutoff=new Date(Date.now()-180*864e5);
  const gravesRecentes=all.filter(ic=>["Grave","Emergencial"].includes(icSeverityOf(ic))&&(()=>{const d=parseAnyDate(ic.date);return d&&d>=recentCutoff;})());
  function groupCount(key){
    const map={};
    gravesRecentes.forEach(ic=>{const k=ic[key];if(!k)return;map[k]=(map[k]||0)+1;});
    return Object.entries(map).filter(([,n])=>n>=3).sort((a,b)=>b[1]-a[1]);
  }
  const padroesProduto=groupCount("product");
  const padroesRegiao=groupCount("region");
  // ── Alerta por LOTE: mais preciso que por produto — cruza intercorrência → sessão → lote consumido.
  // 2+ já é um sinal forte aqui (lote é bem mais específico que "produto"), diferente do limiar de 3+ acima.
  function icLoteCodigos(ic){
    const sess=(ic.patient.sessions||[]).find(s=>String(s.id)===String(ic.sessId));
    if(!sess)return[];
    const items=(sess.items&&sess.items.length)?sess.items:(sess.loteId?[{loteId:sess.loteId}]:[]);
    const codigos=new Set();
    items.forEach(it=>{
      if(!it.loteId)return;
      for(const prod of products){
        const lote=(prod.lotes||[]).find(l=>String(l.id)===String(it.loteId));
        if(lote){codigos.add(JSON.stringify({codigo:lote.codigo,prodName:prod.name}));break;}
      }
    });
    return[...codigos].map(s=>JSON.parse(s));
  }
  const loteMap={};
  gravesRecentes.forEach(ic=>{icLoteCodigos(ic).forEach(({codigo,prodName})=>{const k=codigo+"||"+prodName;loteMap[k]=(loteMap[k]||0)+1;});});
  const padroesLote=Object.entries(loteMap).filter(([,n])=>n>=2).sort((a,b)=>b[1]-a[1]).map(([k,n])=>{
    const[codigo,prodName]=k.split("||");
    let restante=null;
    for(const prod of products){const l=(prod.lotes||[]).find(x=>x.codigo===codigo);if(l){restante=l.qtd;break;}}
    return{codigo,prodName,n,restante};
  });
  const procOptions=["Todos",...Array.from(new Set(all.map(ic=>ic.procedure).filter(Boolean)))];
  const prodOptions=["Todos",...Array.from(new Set(all.map(ic=>ic.product).filter(Boolean)))];
  const filtered=all.filter(ic=>
    (!fPaciente||ic.patient.name.toLowerCase().includes(fPaciente.toLowerCase()))&&
    (fProc==="Todos"||ic.procedure===fProc)&&
    (fProd==="Todos"||ic.product===fProd)&&
    (fSev==="Todas"||icSeverityOf(ic)===fSev)&&
    (fStatus==="Todos"||icStatusOf(ic)===fStatus)
  ).sort((a,b)=>(b.date||"").localeCompare(a.date||""));
  const stats={
    total:all.length,
    acomp:all.filter(ic=>icStatusOf(ic)==="Em Acompanhamento").length,
    resolv:all.filter(ic=>icStatusOf(ic)==="Resolvida").length,
    graves:all.filter(ic=>["Grave","Emergencial"].includes(icSeverityOf(ic))).length,
  };
  const selStyle={padding:"8px 12px",borderRadius:8,background:P.bg3,border:`1px solid ${P.border}`,color:P.text2,fontSize:12.5,fontFamily:"'Jost',system-ui,sans-serif",cursor:"pointer"};
  return h("div",null,
    h(SectionHeader,{title:"Intercorrências",sub:"Painel clínico de intercorrências da clínica"}),
    (padroesProduto.length>0||padroesRegiao.length>0||padroesLote.length>0)&&h(Card,{style:{marginBottom:18,border:`1px solid ${P.statusRed}55`,background:"rgba(182,74,72,.06)"}},
      h("div",{style:{display:"flex",alignItems:"center",gap:8,marginBottom:10}},
        h("span",{style:{fontSize:18}},"⚠️"),
        h("div",{style:{fontFamily:"'Cormorant Garamond',serif",fontSize:16,color:P.statusRed}},"Padrão de reincidência nos últimos 6 meses")
      ),
      h("div",{style:{display:"flex",flexDirection:"column",gap:6}},
        padroesLote.map(l=>h("div",{key:"l-"+l.codigo,style:{fontSize:12.5,color:P.text,fontWeight:600,background:"rgba(182,74,72,.1)",borderRadius:8,padding:"7px 10px"}},
          `🔴 ${l.n}× intercorrência grave/emergencial do LOTE ${l.codigo} (${l.prodName})`,
          l.restante!=null&&h("span",{style:{fontWeight:400,color:P.text2}},l.restante>0?` — ainda há ${l.restante} unidade(s) desse lote no estoque, considere retirar de uso.`:" — lote já esgotado no estoque.")
        )),
        padroesProduto.map(([prod,n])=>h("div",{key:"p-"+prod,style:{fontSize:12.5,color:P.text2}},`💉 ${n}× intercorrência grave/emergencial com "${prod}"`)),
        padroesRegiao.map(([reg,n])=>h("div",{key:"r-"+reg,style:{fontSize:12.5,color:P.text2}},`📍 ${n}× intercorrência grave/emergencial na região "${reg}"`))
      ),
      h("div",{style:{fontSize:11,color:P.text3,marginTop:8}},"Pode indicar lote com problema, técnica a revisar, ou padrão de sensibilidade — vale investigar.")
    ),
    h("div",{className:"resp-grid-4",style:{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:14,marginBottom:18}},
      [{l:"Total Registradas",v:stats.total,c:P.statusPurple},{l:"Em Acompanhamento",v:stats.acomp,c:P.statusBlue},{l:"Resolvidas",v:stats.resolv,c:P.statusGreen},{l:"Graves / Emergenciais",v:stats.graves,c:P.statusRed}].map(s=>
        h(Card,{key:s.l,style:kpiCardStyle(s.c)},
          h("div",{style:{fontSize:10,color:P.text3,textTransform:"uppercase",letterSpacing:".1em",marginBottom:8}},s.l),
          h("div",{style:{fontFamily:"'Cormorant Garamond',serif",fontSize:30,color:s.c}},s.v)
        )
      )
    ),
    h("div",{className:"resp-grid-2",style:{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14,marginBottom:18}},
      h(Card,null,
        h("div",{style:{fontFamily:"'Cormorant Garamond',serif",fontSize:16,color:P.text,marginBottom:10}},"Por Gravidade"),
        IC_SEVERITY.map(sv=>{const n=all.filter(ic=>icSeverityOf(ic)===sv).length;const cfg=IC_SEVERITY_CFG[sv];return h("div",{key:sv,style:{display:"flex",justifyContent:"space-between",padding:"6px 0",borderBottom:`1px solid ${P.border}`}},h("span",{style:{fontSize:12,color:cfg.color}},sv),h("span",{style:{fontSize:15,fontFamily:"'Cormorant Garamond',serif",color:P.text}},n));})
      ),
      h(Card,null,
        h("div",{style:{fontFamily:"'Cormorant Garamond',serif",fontSize:16,color:P.text,marginBottom:10}},"Por Status"),
        IC_STATUS_LIST.map(st=>{const n=all.filter(ic=>icStatusOf(ic)===st).length;const cfg=IC_STATUS_CFG[st];return h("div",{key:st,style:{display:"flex",justifyContent:"space-between",padding:"6px 0",borderBottom:`1px solid ${P.border}`}},h("span",{style:{fontSize:12,color:cfg.color}},st),h("span",{style:{fontSize:15,fontFamily:"'Cormorant Garamond',serif",color:P.text}},n));})
      )
    ),
    h("div",{style:{display:"flex",gap:10,marginBottom:18,flexWrap:"wrap",alignItems:"center"}},
      h("input",{value:fPaciente,onChange:e=>setFPaciente(e.target.value),placeholder:"Buscar paciente...",style:{flex:"1 1 200px",padding:"8px 14px",borderRadius:8,background:P.bg3,border:`1px solid ${P.border}`,color:P.text,fontSize:13,fontFamily:"'Jost',system-ui,sans-serif"}}),
      h("select",{value:fProc,onChange:e=>setFProc(e.target.value),style:selStyle},procOptions.map(o=>h("option",{key:o,value:o},o))),
      h("select",{value:fProd,onChange:e=>setFProd(e.target.value),style:selStyle},prodOptions.map(o=>h("option",{key:o,value:o},o))),
      h("select",{value:fSev,onChange:e=>setFSev(e.target.value),style:selStyle},["Todas",...IC_SEVERITY].map(o=>h("option",{key:o,value:o},o))),
      h("select",{value:fStatus,onChange:e=>setFStatus(e.target.value),style:selStyle},["Todos",...IC_STATUS_LIST].map(o=>h("option",{key:o,value:o},o)))
    ),
    filtered.length===0
      ?h(Card,{style:{textAlign:"center",padding:40}},
          h("div",{style:{fontSize:32,marginBottom:12}},all.length===0?"✅":"🔍"),
          h("div",{style:{color:P.text3,fontSize:14}},all.length===0?"Nenhuma intercorrência registrada na clínica ainda.":"Nenhuma intercorrência encontrada para os filtros selecionados.")
        )
      :filtered.map(ic=>h(IntercorrenciaCard,{key:ic.id,ic,patient:ic.patient,setPatients,showPatientName:true,onSelectPatient,onNav}))
  );
}

// ─── ROOT APP (com autenticação) ─────────────────────────────────────────────
// ─── TELA DE ABERTURA ─────────────────────────────────────────────────────────
// Aparece toda vez que o sistema abre: enquanto os dados chegam e por um instante depois, com a saudação.
function SplashScreen({nome,linha,leaving}){
  const h=createElement;
  const hr=new Date().getHours();
  const saud=hr<5?"Boa noite":hr<12?"Bom dia":hr<18?"Boa tarde":"Boa noite";
  const dataTxt=(()=>{const t=new Date().toLocaleDateString("pt-BR",{weekday:"long",day:"numeric",month:"long"});return t.charAt(0).toUpperCase()+t.slice(1);})();
  const dark=P===P_DARK||P.bg===P_DARK.bg;
  return h("div",{"aria-hidden":true,style:{position:"fixed",inset:0,zIndex:9999,display:"flex",alignItems:"center",justifyContent:"center",
      background:dark?"radial-gradient(120% 90% at 50% 35%,#2A1216 0%,#160A0C 70%)":"radial-gradient(120% 90% at 50% 35%,#FDFAF7 0%,#F3E8E1 75%)",
      opacity:leaving?0:1,transition:"opacity .6s ease",pointerEvents:leaving?"none":"auto"}},
    h("style",null,`
      @keyframes hpIcon{from{opacity:0;transform:scale(.86)}to{opacity:1;transform:none}}
      @keyframes hpRise{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
      @keyframes hpBreath{0%,100%{opacity:.55}50%{opacity:1}}
    `),
    h("div",{style:{display:"flex",flexDirection:"column",alignItems:"center",textAlign:"center",padding:24}},
      h("img",{src:APP_ICON,alt:"",style:{width:92,height:92,borderRadius:22,marginBottom:24,boxShadow:dark?"0 18px 40px -16px rgba(0,0,0,.7)":"0 20px 44px -20px rgba(90,31,49,.55)",animation:"hpIcon 1s cubic-bezier(.22,1,.36,1) both"}}),
      h("div",{style:{fontFamily:"'Cormorant Garamond',serif",fontSize:30,color:dark?"#F1E4DE":"#3B1A22",letterSpacing:".04em",animation:"hpRise .8s ease .2s both"}},"HarmonizaPro"),
      h("div",{style:{width:36,height:1,background:dark?"rgba(217,163,163,.4)":"rgba(122,46,63,.3)",margin:"16px 0",animation:"hpRise .8s ease .35s both"}}),
      h("div",{style:{fontFamily:"'Cormorant Garamond',serif",fontStyle:"italic",fontSize:21,color:dark?"#E4C9C2":"#7A2E3F",animation:"hpRise .8s ease .5s both"}},saud+(nome?", "+nome:"")),
      h("div",{style:{fontFamily:"'Jost',system-ui,sans-serif",fontSize:11,letterSpacing:".22em",textTransform:"uppercase",color:dark?"#A89290":"#9C8681",marginTop:10,animation:"hpRise .8s ease .65s both"}},dataTxt),
      h("div",{style:{fontFamily:"'Jost',system-ui,sans-serif",fontSize:12.5,fontWeight:300,color:dark?"#C9B5B0":"#6E5752",marginTop:18,minHeight:18,animation:linha?"hpRise .6s ease both":"hpBreath 1.6s ease-in-out infinite"}},linha||"Preparando seu dia…")
    )
  );
}
function App(){
  const [session, setSession] = useState(null);
  const [authLoading, setAuthLoading] = useState(true);
  const hadSessionRef = useRef(false);
  const sessionRef = useRef(null); // guarda a sessão atual para saber de quem limpar o cache ao sair
  useEffect(() => { sessionRef.current = session; }, [session]);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session: s }, error }) => {
      if (error || !s) {
        // Token inválido ou expirado — limpa e vai para login
        supabase.auth.signOut().catch(() => {});
        setSession(null);
      } else {
        setSession(s);
        hadSessionRef.current = true; // já chegou logada (refresh de página) — não mostra a transição de entrada
      }
      setAuthLoading(false);
    }).catch(() => { setAuthLoading(false); });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, s) => {
      if (event === "TOKEN_REFRESHED" || event === "SIGNED_IN") {
        // Dispara a transição de entrada NO MESMO INSTANTE em que a sessão muda (não numa renderização
        // separada depois) — assim a tela de boas-vindas já nasce por cima do Dashboard, sem piscar.
        if (event === "SIGNED_IN" && !hadSessionRef.current) hadSessionRef.current = true;
        setSession(s);
      } else if (event === "SIGNED_OUT" || !s) {
        try { const uidOut = sessionRef.current?.user?.id; clearLocalPatientData(uidOut); } catch {}
        setSession(null);
        hadSessionRef.current = false;
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  if (authLoading) return createElement(SplashScreen, {});

  if (!session) return createElement(LoginScreen, { onLogin: () => supabase.auth.getSession().then(({data:{session:s}})=>setSession(s)) });

  return createElement(Fragment, null,
    createElement(AppInner, { session, onLogout: () => { clearLocalPatientData(session?.user?.id); return supabase.auth.signOut(); } }),
    createElement(ToastHost, {})
  );
}

// ─── VOUCHER / GIFT CARD ──────────────────────────────────────────────────────
const DEFAULT_VOUCHER_TEMPLATES=[
  {k:"aniversario",l:"🎂 Aniversário",grad:"linear-gradient(135deg,#d88aa8,#E6A592)"},
  {k:"namorados",l:"💕 Dia dos Namorados",grad:"linear-gradient(135deg,#c0617e,#e0937a)"},
  {k:"natal",l:"🎄 Natal",grad:"linear-gradient(135deg,#3f7a5e,#c0617e)"},
  {k:"maes",l:"💐 Dia das Mães",grad:"linear-gradient(135deg,#d49bc4,#EAB6A7)"},
  {k:"indicacao",l:"🤝 Indicação",grad:"linear-gradient(135deg,#8FADD6,#9b7aad)"},
  {k:"classico",l:"✦ Clássico HarmonizaPro",grad:`linear-gradient(135deg,${P.rose},${P.gold})`},
];
function genVoucherCode(){
  const chars="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let s="";for(let i=0;i<8;i++)s+=chars[Math.floor(Math.random()*chars.length)];
  return "HP-"+s.slice(0,4)+"-"+s.slice(4);
}
function voucherStatus(v){
  if(v.status==="cancelado")return "cancelado";
  const exp=v.validUntil?new Date(v.validUntil+"T23:59:59"):null;
  const expired=exp&&exp<new Date();
  if(v.type==="valor"){
    const saldo=Number(v.value)-Number(v.usedValue||0);
    if(saldo<=0)return "usado";
    if(expired)return "expirado";
    return saldo<Number(v.value)?"parcial":"ativo";
  } else {
    if(v.used)return "usado";
    if(expired)return "expirado";
    return "ativo";
  }
}
const VOUCHER_STATUS_CFG={
  ativo:{l:"Ativo",color:P.green,bg:"rgba(122,173,138,.13)"},
  parcial:{l:"Parcialmente Usado",color:P.yellow,bg:"rgba(187,132,115,.13)"},
  usado:{l:"Utilizado",color:P.text3,bg:"rgba(255,255,255,.05)"},
  expirado:{l:"Expirado",color:P.red,bg:"rgba(192,112,112,.13)"},
  cancelado:{l:"Cancelado",color:P.red,bg:"rgba(192,112,112,.08)"},
};

// ─── ARTE DO VOUCHER (imagem 1080×1350 para WhatsApp / Instagram) ─────────────
const VOUCHER_LIGHT_TPLS=["aniversario","maes","namorados"];
function voucherTema(tplK){
  return VOUCHER_LIGHT_TPLS.includes(tplK)
    ?{light:true,bg1:"#FBF6F1",bg2:"#EFE1D8",ink:"#4A1A28",soft:"#8C6B66",line:"rgba(90,31,49,.28)",logo:LOGO_MONO_WINE,codeBg:"rgba(90,31,49,.06)"}
    :{light:false,bg1:"#3A1520",bg2:"#6E2B40",ink:"#F4E9DF",soft:"#D8BFB6",line:"rgba(244,233,223,.32)",logo:LOGO_MONO_CREAM,codeBg:"rgba(244,233,223,.08)"};
}
function _loadImg(src){return new Promise(res=>{const i=new Image();i.onload=()=>res(i);i.onerror=()=>res(null);i.src=src;});}
async function renderVoucherArt(v,tpl,settings){
  const W=1080,H=1350;
  const cv=document.createElement("canvas");cv.width=W;cv.height=H;const x=cv.getContext("2d");
  const T=voucherTema(tpl&&tpl.k);
  try{await Promise.all(['400 90px "Cormorant Garamond"','italic 400 40px "Cormorant Garamond"','300 26px "Jost"','400 26px "Jost"'].map(f=>document.fonts.load(f)));}catch(e){}
  const serif='"Cormorant Garamond", Georgia, serif',sans='"Jost", "Helvetica Neue", Arial, sans-serif';
  // fundo
  const g=x.createLinearGradient(0,0,W,H);g.addColorStop(0,T.bg1);g.addColorStop(1,T.bg2);x.fillStyle=g;x.fillRect(0,0,W,H);
  const rg=x.createRadialGradient(W/2,H*0.3,40,W/2,H*0.3,W*0.8);rg.addColorStop(0,T.light?"rgba(255,255,255,.55)":"rgba(255,220,210,.10)");rg.addColorStop(1,"rgba(255,255,255,0)");x.fillStyle=rg;x.fillRect(0,0,W,H);
  // molduras
  const rr=(m,r)=>{x.beginPath();x.moveTo(m+r,m);x.lineTo(W-m-r,m);x.quadraticCurveTo(W-m,m,W-m,m+r);x.lineTo(W-m,H-m-r);x.quadraticCurveTo(W-m,H-m,W-m-r,H-m);x.lineTo(m+r,H-m);x.quadraticCurveTo(m,H-m,m,H-m-r);x.lineTo(m,m+r);x.quadraticCurveTo(m,m,m+r,m);x.closePath();};
  x.strokeStyle=T.line;x.lineWidth=1.6;rr(44,26);x.stroke();
  x.globalAlpha=.5;x.lineWidth=1;rr(58,18);x.stroke();x.globalAlpha=1;
  x.textAlign="center";x.textBaseline="alphabetic";
  const spaced=(txt,y,font,color,sp)=>{x.font=font;x.fillStyle=color;const cs=[...String(txt)];const ws=cs.map(c=>x.measureText(c).width);const tot=ws.reduce((a,b)=>a+b,0)+sp*(cs.length-1);let cx=W/2-tot/2;x.textAlign="left";cs.forEach((c,i)=>{x.fillText(c,cx,y);cx+=ws[i]+sp;});x.textAlign="center";};
  const wrap=(txt,maxW,font)=>{x.font=font;const words=String(txt||"").split(/\s+/).filter(Boolean);const lines=[];let cur="";words.forEach(w=>{const t=cur?cur+" "+w:w;if(x.measureText(t).width>maxW&&cur){lines.push(cur);cur=w;}else cur=t;});if(cur)lines.push(cur);return lines;};
  // logo
  let y=118;
  const logo=await _loadImg(T.logo);
  if(logo){const lh=150,lw=logo.width*lh/logo.height;x.drawImage(logo,W/2-lw/2,y,lw,lh);y+=lh;}
  const clin=String((settings&&settings.clinicName)||"").trim();
  if(clin&&!/harmonizapro/i.test(clin)){y+=50;spaced(clin.toUpperCase(),y,`400 21px ${sans}`,T.soft,7);}
  // título
  const ocasiao=stripAllEmoji((tpl&&tpl.l)||"").replace(/harmonizapro/i,"").trim();
  y+=clin&&!/harmonizapro/i.test(clin)?78:86;
  spaced("VALE-PRESENTE"+(ocasiao&&!/cl[aá]ssico/i.test(ocasiao)?"  ·  "+ocasiao.toUpperCase():""),y,`400 22px ${sans}`,T.soft,6);
  y+=78;x.font=`italic 400 40px ${serif}`;x.fillStyle=T.soft;x.fillText("para",W/2,y);
  y+=92;let nf=96;x.font=`400 ${nf}px ${serif}`;while(x.measureText(v.toName||"").width>W-260&&nf>56){nf-=4;x.font=`400 ${nf}px ${serif}`;}
  x.fillStyle=T.ink;x.fillText(v.toName||"",W/2,y);
  // ornamento
  y+=58;x.strokeStyle=T.line;x.lineWidth=1.4;x.beginPath();x.moveTo(W/2-120,y);x.lineTo(W/2-16,y);x.moveTo(W/2+16,y);x.lineTo(W/2+120,y);x.stroke();
  x.save();x.translate(W/2,y);x.rotate(Math.PI/4);x.fillStyle=T.soft;x.fillRect(-5,-5,10,10);x.restore();
  // presente
  y+=40;
  if(v.type==="valor"){
    y+=96;x.font=`400 112px ${serif}`;x.fillStyle=T.ink;x.fillText(Number(v.value||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL",minimumFractionDigits:0,maximumFractionDigits:2}),W/2,y);
    y+=60;spaced("EM PROCEDIMENTOS",y,`300 20px ${sans}`,T.soft,6);
  }else{
    const ls=wrap((v.procedures||[]).join("  ·  "),W-280,`400 50px ${serif}`).slice(0,3);
    ls.forEach(l=>{y+=64;x.font=`400 50px ${serif}`;x.fillStyle=T.ink;x.fillText(l,W/2,y);});
  }
  // mensagem
  if(v.message){
    y+=40;const ls=wrap("“"+v.message+"”",W-300,`italic 400 36px ${serif}`).slice(0,4);
    ls.forEach(l=>{y+=48;x.font=`italic 400 36px ${serif}`;x.fillStyle=T.ink;x.globalAlpha=.88;x.fillText(l,W/2,y);x.globalAlpha=1;});
  }
  if(v.fromName){y+=60;x.font=`300 26px ${sans}`;x.fillStyle=T.soft;x.fillText("com carinho, "+v.fromName,W/2,y);}
  // código e validade (rodapé)
  const by=H-250;
  x.fillStyle=T.codeBg;x.strokeStyle=T.line;x.lineWidth=1.2;
  const bw=470,bh=104;x.beginPath();const bx=W/2-bw/2;const r=52;x.moveTo(bx+r,by);x.lineTo(bx+bw-r,by);x.arc(bx+bw-r,by+r,r,-Math.PI/2,Math.PI/2);x.lineTo(bx+r,by+bh);x.arc(bx+r,by+r,r,Math.PI/2,Math.PI*1.5);x.closePath();x.fill();x.stroke();
  spaced("CÓDIGO",by+36,`400 15px ${sans}`,T.soft,5);
  spaced(v.code||"",by+80,`400 34px ${sans}`,T.ink,5);
  const val=v.validUntil?"Válido até "+new Date(v.validUntil+"T12:00").toLocaleDateString("pt-BR"):"";
  const prof=String((settings&&settings.doctorName)||"").trim();
  if(val){x.font=`300 23px ${sans}`;x.fillStyle=T.soft;x.fillText(val+(prof?"  ·  "+prof:""),W/2,by+156);}
  else if(prof){x.font=`300 23px ${sans}`;x.fillStyle=T.soft;x.fillText(prof,W/2,by+156);}
  return cv.toDataURL("image/png");
}
async function shareVoucherArt(dataUrl,v){
  const nome=`vale-presente-${String(v.toName||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9]+/g,"-")||v.code}.png`;
  try{
    const blob=await (await fetch(dataUrl)).blob();
    const file=new File([blob],nome,{type:"image/png"});
    if(navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({files:[file],title:"Vale-presente"});return;}
  }catch(e){if(e&&e.name==="AbortError")return;}
  const a=document.createElement("a");a.href=dataUrl;a.download=nome;document.body.appendChild(a);a.click();a.remove();
}
